import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { authAPI } from '../services/api';
import { useAuth } from '../context/AuthContext';

const SignupPage = () => {
  const [form, setForm] = useState({ name: '', email: '', password: '', confirm: '' });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const { login } = useAuth();
  const navigate = useNavigate();

  const handleChange = (e) => {
    setForm(prev => ({ ...prev, [e.target.name]: e.target.value }));
    setError('');
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!form.name || !form.email || !form.password) {
      setError('All fields are required.');
      return;
    }
    if (form.password.length < 6) {
      setError('Password must be at least 6 characters.');
      return;
    }
    if (form.password !== form.confirm) {
      setError('Passwords do not match.');
      return;
    }

    setLoading(true);
    try {
      const res = await authAPI.signup({ name: form.name, email: form.email, password: form.password });
      login(res.data.token, res.data.user);
      navigate('/chat');
    } catch (err) {
      setError(err.response?.data?.message || 'Signup failed. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={styles.page}>
      <div style={styles.bgOrb1} />
      <div style={styles.bgOrb2} />

      <div style={styles.card} className="animate-in">
        <div style={styles.logo}>
          <span style={styles.logoIcon}>⬡</span>
          <span style={styles.logoText}>DocuMind</span>
        </div>

        <h1 style={styles.heading}>Create account</h1>
        <p style={styles.sub}>Start querying your documents with AI</p>

        <form onSubmit={handleSubmit} style={styles.form}>
          {[
            { name: 'name', label: 'Full Name', type: 'text', placeholder: 'Jane Smith' },
            { name: 'email', label: 'Email', type: 'email', placeholder: 'you@example.com' },
            { name: 'password', label: 'Password', type: 'password', placeholder: '••••••••' },
            { name: 'confirm', label: 'Confirm Password', type: 'password', placeholder: '••••••••' },
          ].map(field => (
            <div key={field.name} style={styles.field}>
              <label style={styles.label}>{field.label}</label>
              <input
                name={field.name}
                type={field.type}
                value={form[field.name]}
                onChange={handleChange}
                placeholder={field.placeholder}
                style={styles.input}
                autoComplete={field.name === 'confirm' ? 'new-password' : field.name}
              />
            </div>
          ))}

          {error && <p style={styles.error}>{error}</p>}

          <button type="submit" disabled={loading} style={{ ...styles.btn, ...(loading ? styles.btnDisabled : {}) }}>
            {loading ? (
              <span style={styles.loadingRow}>
                <span style={styles.spinner} /> Creating account...
              </span>
            ) : 'Create Account'}
          </button>
        </form>

        <p style={styles.switchText}>
          Already have an account?{' '}
          <Link to="/login" style={styles.switchLink}>Sign in</Link>
        </p>
      </div>
    </div>
  );
};

const styles = {
  page: {
    minHeight: '100vh',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    background: 'var(--bg-base)',
    position: 'relative',
    overflow: 'hidden',
    padding: '24px',
  },
  bgOrb1: {
    position: 'absolute',
    width: '500px', height: '500px', borderRadius: '50%',
    background: 'radial-gradient(circle, rgba(124,106,247,0.08) 0%, transparent 70%)',
    top: '-150px', right: '-150px', pointerEvents: 'none',
  },
  bgOrb2: {
    position: 'absolute',
    width: '400px', height: '400px', borderRadius: '50%',
    background: 'radial-gradient(circle, rgba(124,106,247,0.05) 0%, transparent 70%)',
    bottom: '-100px', left: '-100px', pointerEvents: 'none',
  },
  card: {
    width: '100%', maxWidth: '420px',
    background: 'var(--bg-surface)',
    border: '1px solid var(--border)',
    borderRadius: 'var(--radius-xl)',
    padding: '40px',
    position: 'relative',
  },
  logo: { display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '28px' },
  logoIcon: { fontSize: '26px', color: 'var(--accent)', filter: 'drop-shadow(0 0 10px var(--accent))' },
  logoText: { fontFamily: 'var(--font-display)', fontWeight: 800, fontSize: '20px', color: 'var(--text-primary)', letterSpacing: '-0.03em' },
  heading: { fontFamily: 'var(--font-display)', fontSize: '28px', fontWeight: 800, color: 'var(--text-primary)', marginBottom: '6px', letterSpacing: '-0.03em' },
  sub: { fontSize: '14px', color: 'var(--text-secondary)', marginBottom: '28px', fontWeight: 300 },
  form: { display: 'flex', flexDirection: 'column', gap: '14px' },
  field: { display: 'flex', flexDirection: 'column', gap: '6px' },
  label: { fontSize: '12px', fontWeight: 500, color: 'var(--text-secondary)', fontFamily: 'var(--font-mono)', textTransform: 'uppercase', letterSpacing: '0.06em' },
  input: { background: 'var(--bg-elevated)', border: '1px solid var(--border)', borderRadius: 'var(--radius-md)', color: 'var(--text-primary)', fontSize: '14px', padding: '11px 14px', transition: 'border-color 0.2s', fontFamily: 'var(--font-body)', fontWeight: 300 },
  error: { fontSize: '13px', color: 'var(--error)', background: 'var(--error-dim)', padding: '10px 14px', borderRadius: 'var(--radius-sm)' },
  btn: { padding: '12px', background: 'var(--accent)', color: '#fff', borderRadius: 'var(--radius-md)', fontSize: '15px', fontWeight: 600, fontFamily: 'var(--font-body)', border: 'none', cursor: 'pointer', marginTop: '4px', transition: 'all 0.2s', boxShadow: 'var(--shadow-accent)' },
  btnDisabled: { background: 'var(--border)', boxShadow: 'none', cursor: 'not-allowed' },
  loadingRow: { display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '8px' },
  spinner: { display: 'inline-block', width: '14px', height: '14px', border: '2px solid rgba(255,255,255,0.3)', borderTopColor: '#fff', borderRadius: '50%', animation: 'spin 0.7s linear infinite' },
  switchText: { marginTop: '24px', textAlign: 'center', fontSize: '13px', color: 'var(--text-secondary)', fontWeight: 300 },
  switchLink: { color: 'var(--accent-light)', fontWeight: 500 },
};

export default SignupPage;
